    if frames is not None:
        for index, (start, _) in enumerate(pairs):
            if start in frames[0]:
                raise ValueError(
                    f"requests[{index}] start {start} is blocked at "
                    f"frame 0"
                )
    # The waiting flag keeps ``plan``'s position right after the
